function enrichDemo(d){if(d.speciesEdition===3)return;const additions=[['p-cat','奶盖','猫','家猫','cat',4.1],['p-bird','青柠','鸟','虎皮鹦鹉','bird',.035],['p-lizard','芝麻','蜥蜴','豹纹守宫','lizard',.055],['p-hamster','布丁','仓鼠','金丝熊','hamster',.12],['p-rabbit','棉花','兔','垂耳兔','rabbit',1.8],['p-turtle','慢慢','龟','草龟','turtle',.23],['p-fish','泡泡','鱼','金鱼','fish',.025]];for(const [id,name,type,breed,photo,value] of additions){if(d.pets.some(p=>p.id===id))continue;d.pets.push({id,name,type,breed,photo,city:'上海',district:'徐汇区',size:'小型',sex:'未填写',intent:'经验交流',time:'周末',personality:'慢热'});d.records.push({id:id+'-weight',pet:id,kind:'体重',day:daysAgo(1),value,photos:[],memo:'示例测量值，仅用于体验记录功能。',created:1},{id:id+'-daily',pet:id,kind:'日常',day:today(),title:name+'的普通一天',memo:'每一种陪伴，都有值得收藏的小事。',photos:[P[photo]],created:2});if(!['狗','猫'].includes(type))d.records.push({id:id+'-care',pet:id,kind:'护理',day:today(),title:type==='鱼'?'换水与环境观察':type==='蜥蜴'?'环境与蜕皮观察':'日常环境清洁',memo:speciesCare(type),photos:[],created:3});}d.speciesEdition=3;}
function fresh(demo){const pet={id:'p1',name:demo?'小满':'我的宠物',type:'狗',breed:demo?'博美':'',photo:demo?'pomeranian':'',birthday:'',arrival:demo?daysAgo(365):'',city:'上海',district:'徐汇区',size:'小型',sex:'未填写',personality:'慢热',intent:'遛宠搭子',time:'周末'};return {pets:demo?[pet]:[],current:demo?'p1':'',records:demo?[{id:'r1',pet:'p1',kind:'日常',day:daysAgo(0),title:'把傍晚交给草地和小狗',memo:'天气刚刚好，今天又发现了一条喜欢的散步路线。',photos:[P.walk],created:6},{id:'r2',pet:'p1',kind:'体重',day:daysAgo(1),value:2.9,memo:'同一台秤，晚饭前测量。',photos:[],created:5},{id:'r3',pet:'p1',kind:'驱虫',day:daysAgo(25),title:'体外驱虫',subtype:'体外',product:'示例护理记录',next:daysAgo(-3),memo:'下次日期为演示计划，请以实际兽医建议为准。',photos:[],created:4},{id:'r4',pet:'p1',kind:'体重',day:daysAgo(15),value:2.85,photos:[],created:3},{id:'r5',pet:'p1',kind:'疫苗',day:daysAgo(60),title:'年度接种记录',next:daysAgo(-28),memo:'示例接种记录。',photos:[],created:2},{id:'r6',pet:'p1',kind:'体重',day:daysAgo(32),value:2.8,photos:[],created:1},{id:'r7',pet:'p1',kind:'里程碑',day:daysAgo(365),title:'第一次来到我身边',memo:'从今天开始，我们就是一家人了。',photos:[P.pomeranian],created:0}]:[],posts:[],comments:{},likes:[],bookmarks:[],following:[],blocked:[],reports:[],invites:[],profile:{name:'养宠人',city:'上海',district:'徐汇区',bio:''},privacy:{nearby:false},draft:null}}
function readState(){try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s?.version===2&&s.personal&&s.demo)return s}catch{}const s={version:2,mode:'demo',seen:false,demo:fresh(true),personal:fresh(false)};try{const old=JSON.parse(localStorage.getItem('pawdiary-records')||'[]');if(Array.isArray(old)&&old.length){s.personal.pets=[{id:'legacy',name:'小满',type:'狗',breed:'博美',city:'',district:'',sex:'未填写'}];s.personal.current='legacy';s.personal.records=old.map((r,i)=>({...r,id:uid(),pet:'legacy',created:old.length-i,title:r.kind==='体重'?'':r.value,photos:[]}));s.mode='personal';s.seen=true}}catch{}return s}
let state=readState();enrichDemo(state.demo);let tab='home',growthView='全部记录',recordFilter='全部',range=90,feedView='推荐',feedSpecies='全部宠物',topic='全部',near={city:'上海',district:'全部区域',type:'全部宠物',size:'全部体型',personality:'全部性格',intent:'全部意向',time:'全部时间'},pendingPhotos=[],modalDirty=false,modalDraftType=null,returnAfter=null;
const db=()=>state[state.mode],pet=()=>db().pets.find(p=>p.id===db().current)||db().pets[0],isDemo=()=>state.mode==='demo';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('空间不足，内容未能保存。请减少照片或导出备份后重试。');return false}}
function transact(fn){const before=JSON.stringify(state);fn();if(!persist()){state=JSON.parse(before);return false}return true}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function records(){return db().records.filter(r=>r.pet===pet()?.id).sort((a,b)=>b.day.localeCompare(a.day)||(b.created||0)-(a.created||0))}
function weight(){return records().find(r=>r.kind==='体重'&&Number(r.value)>0)}
function photo(p){return p?.photo?.startsWith('data:image/')?p.photo:P[p?.photo]||''}
const image=(src,cls='',alt='宠物照片')=>src?`<img src="${esc(src)}" class="${cls}" alt="${esc(alt)}" loading="lazy">`:`<span class="${cls} avatar-placeholder">${icon(speciesIcon(pet()?.type))}</span>`;
const act=(name,label,cls='',data='')=>`<button type="button" class="${cls}" data-action="${name}" ${data}>${label}</button>`;
function demoNotice(){return `<div class="demo-notice"><span>${isDemo()?'示例体验 · 宠友与互动为本机演示':'个人空间 · 记录保存在当前浏览器'}</span>${act(isDemo()?'personal':'demo',isDemo()?'建立我的档案':'体验示例')}</div>`}
function nav(){const items=[['home','首页'],['growth','成长'],['near','附近'],['community','社区'],['profile','我的']];const html=items.map(([id,name])=>`<button data-nav="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(id==='near'?'pin':id==='profile'?'user':id)}<span>${name}</span></button>`).join('');$('#bottomnav').innerHTML=html;$('#sidebar').innerHTML=`<div class="brand"><span class="brandmark">${icon('dog')}</span><div>爪爪日记<small>PAWDIARY</small></div></div><div class="side-links">${html}</div><div class="side-foot">陪它慢慢长大。<br>Every little moment matters.<br><br>${isDemo()?'示例体验空间':'我的宠物空间'} · V3</div>`;$('#header').innerHTML=`<div class="brand"><span class="brandmark">${icon('dog')}</span>爪爪日记</div><span class="breadcrumb">PAWDIARY / ${items.find(x=>x[0]===tab)[1]}</span><div class="header-actions">${pet()?act('switchpet',esc(pet().name)+'⌄','textbtn'):''}${act('feedback',icon('community'),'icon-btn','aria-label="意见与建议"')}${act('reminders',icon('bell')+(plans().some(r=>dayDiff(r.next)<=7)?'<i class="badge-dot"></i>':''),'icon-btn','aria-label="护理提醒"')}<div class="userbadge">${esc(db().profile.name.slice(0,1))}</div></div>`}
function title(eyebrow,h,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${h}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>${action}</div>`}
function empty(h,p,button=''){return `<div class="empty"><div class="empty-icon">${icon('leaf')}</div><h3>${h}</h3><p>${p}</p>${button}</div>`}
function needPet(){return empty('猫、鸟、蜥蜴、仓鼠……每一种陪伴，都从名字开始','为它建立一个档案，把往后的成长慢慢记下来。',act('newpet','添加我的宠物','btn'))}
function petHero(){const p=pet();if(!p)return `<div class="card">${needPet()}</div>`;const w=weight();return `<article class="card pet-hero"><div class="pet-copy"><span class="pill">${icon(speciesIcon(p.type))} ${isDemo()?'示例宠物档案':'我的家庭成员'}</span><h2>${esc(p.name)}</h2><p class="tiny muted">${esc(p.breed||p.type)}${p.birthday?' · '+age(p.birthday):''}</p><div class="pet-stats"><div><b>${w?weightNumber(w.value).toFixed(weightUnit()==='g'?1:2):'—'}<span class="tiny"> ${weightUnit()}</span></b><small>${w?'最近体重 · '+shortDate(w.day):'还没有体重记录'}</small></div><div><b>${records().length}</b><small>个成长瞬间</small></div></div>${act('petdetail','查看档案 '+icon('arrow'),'textbtn')}</div>${photo(p)?image(photo(p),'pet-photo',p.name):''}</article>`}
function age(b){const n=Math.max(0,-dayDiff(b)),years=Math.floor(n/365);return years?years+'岁':Math.floor(n/30)+'个月'}
function plans(){const seen=new Set();return records().filter(r=>{if(!['疫苗','驱虫'].includes(r.kind))return false;const k=r.kind+(r.kind==='驱虫'?r.subtype||'':r.title);if(seen.has(k))return false;seen.add(k);return !!r.next}).sort((a,b)=>a.next.localeCompare(b.next))}
function planRows(list){return list.map(r=>{const n=dayDiff(r.next),text=n<0?'超过计划 '+(-n)+' 天':n===0?'计划今天完成':'还有 '+n+' 天';return `<div class="care-row"><span class="care-icon">${icon(types[r.kind])}</span><div class="care-copy"><b>${esc(r.title||r.subtype+'驱虫')}</b><small>${esc(r.next)} · ${r.kind}</small><span class="status ${n<0?'late':n<=7?'warn':''}">${text}</span></div>${act('complete','去记录','btn light small',`data-id="${r.id}"`)}</div>`}).join('')}
function recordCard(r,actions=true){return `<article class="timeline-item"><span class="timeline-marker">${icon(types[r.kind])}</span><div class="timeline-body"><div class="timeline-date">${esc(r.day)}<span>${esc(r.kind)} · ${db().posts.some(p=>p.source===r.id)?'已分享':'仅自己'}</span></div><h3>${esc(r.kind==='体重'?weightText(r.value):r.title||r.kind)}</h3>${r.memo?`<p>${esc(r.memo)}</p>`:''}${r.photos?.[0]?act('viewrecord',image(r.photos[0],'timeline-thumb','记录照片'),'',`data-id="${r.id}"`):''}${actions?`<div class="record-actions">${act('editrecord','编辑','',`data-id="${r.id}"`)}${act('deleterecord','删除','',`data-id="${r.id}"`)}${['日常','里程碑'].includes(r.kind)?act('sharerecord','分享至社区','',`data-id="${r.id}"`):''}</div>`:''}</div></article>`}
function home(){const city=pet()?.city||db().profile.city,localFriends=friends.filter(f=>f.city===city&&!db().blocked.includes(f.id)).sort((a,b)=>Number(b.type===pet()?.type)-Number(a.type===pet()?.type)).slice(0,2);return title('A LITTLE CARE, EVERY DAY','一起长大，把爱记下来。','照顾好每一天，也收藏小小的成长瞬间。')+demoNotice()+`<div class="species-strip" aria-label="宠物类型体验">${PET_TYPES.filter(t=>t!=='其他').map(t=>{const q=db().pets.find(p=>p.type===t);return act(q?'selectpet':'newpet',icon(speciesIcon(t))+`<span>${t}</span>`,'species-button '+(pet()?.type===t?'active':''),q?`data-id="${q.id}"`:`data-kind="${t}"`)}).join('')}</div><div class="hero">${petHero()}<section class="card quick-card"><div class="section-title"><h2>今天，记一笔</h2><span class="muted">从一个小瞬间开始</span></div><div class="quick-grid">${careKinds().map(k=>act('record',`<span class="quick-icon">${icon(types[k])}</span><span>记${k}</span>`,'quick-item',`data-kind="${k}"`)).join('')}</div><p class="tiny muted" style="padding:14px 7px 0">${icon('shield')} 私人记录，由你决定是否分享。</p></section></div><div class="home-grid"><div class="stack"><section class="card"><div class="section-title"><h2>近期照护</h2>${act('reminders','全部 '+icon('arrow'),'textbtn')}</div>${plans().length?planRows(plans().slice(0,3)):empty('每一种宠物，都值得细心照护',speciesCare(pet()?.type),act('record','添加护理记录','btn light small',`data-kind="${['狗','猫'].includes(pet()?.type)?'疫苗':'护理'}"`))}</section><section class="card"><div class="section-title"><h2>最近的成长</h2>${act('allrecords','全部 '+icon('arrow'),'textbtn')}</div>${records().slice(0,3).map(r=>recordCard(r,false)).join('')||empty('故事，从第一篇开始','记下今天值得留住的小事。',act('record','记录日常','btn light small','data-kind="日常"'))}</section></div><div class="stack"><section class="card"><div class="section-title"><h2>同城的小伙伴</h2>${act('near','去看看 '+icon('arrow'),'textbtn')}</div><p class="tiny muted" style="margin-bottom:16px">${esc(city||'选择地区')} · 示例宠友，发现同样热爱陪伴的人</p><div class="mini-pets">${localFriends.map(f=>act('friend',`${image(P[f.photo],'avatar-img',f.name)}<span><b>${f.name}</b><small>${f.breed} · ${f.district}</small></span>`,'mini-pet',`data-id="${f.id}"`)).join('')}</div></section><section class="card quote"><div class="eyebrow">LITTLE FRIENDS, BIG MEMORIES</div><p>它的每一天，<br>都有你参与的痕迹。</p><span class="tiny muted">不用很特别，日常就值得珍藏。</span></section></div></div>`}
function chart(ws){if(!ws.length)return empty('还没有体重数据','从第一次测量开始，了解它的变化。',act('record','记录体重','btn light','data-kind="体重"'));const sorted=[...ws].reverse(),vals=sorted.map(r=>weightNumber(r.value)),lo=Math.max(0,Math.min(...vals)-(weightUnit()==='g'?5:.15)),hi=Math.max(...vals)+(weightUnit()==='g'?5:.15),first=new Date(sorted[0].day+'T12:00:00').getTime(),last=new Date(sorted.at(-1).day+'T12:00:00').getTime();const pts=sorted.map(r=>({x:sorted.length===1?210:42+(new Date(r.day+'T12:00:00').getTime()-first)/(last-first||1)*330,y:155-(weightNumber(r.value)-lo)/(hi-lo)*115,r}));return `<svg class="chart" viewBox="0 0 420 195" role="img" aria-label="体重历史曲线，单位${weightUnit()}">${[lo,(lo+hi)/2,hi].map(v=>{const y=155-(v-lo)/(hi-lo)*115;return `<line x1="40" y1="${y}" x2="390" y2="${y}" stroke="#e8ecdf" stroke-dasharray="3 4"/><text x="3" y="${y+4}">${v.toFixed(2)}</text>`}).join('')}${pts.length>1?`<polyline points="${pts.map(p=>p.x+','+p.y).join(' ')}" stroke="#68834e" fill="none" stroke-width="2.5"/>`:''}${pts.map(p=>`<circle tabindex="0" data-action="weightpoint" data-id="${p.r.id}" cx="${p.x}" cy="${p.y}" r="5" fill="#fff" stroke="#68834e" stroke-width="2"><title>${p.r.day} · ${weightText(p.r.value)}</title></circle>`).join('')}<text x="42" y="184">${shortDate(sorted[0].day)}</text><text x="344" y="184">${shortDate(sorted.at(-1).day)}</text></svg><p class="tiny muted">点击数据点查看记录 · 曲线呈现变化，不作为健康诊断</p>`}
function health(){const all=records().filter(r=>r.kind==='体重'),ws=all.filter(r=>range===0||-dayDiff(r.day)<=range),w=all[0],diff=all.length>1?Number(w.value)-Number(all[1].value):null;return `<div class="health-grid"><div class="stack"><section class="card"><div class="section-title"><h2>体重变化</h2>${act('record',icon('plus'),'icon-btn','data-kind="体重" aria-label="添加体重"')}</div><div class="metric">${w?weightNumber(w.value).toFixed(weightUnit()==='g'?1:2):'—'} <small>${weightUnit()}</small></div><p class="tiny muted">${w?'最近测量 '+w.day:'还没有记录'}${diff!==null?' · 较上次'+(diff>=0?'增加 ':'减少 ')+weightNumber(Math.abs(diff)).toFixed(weightUnit()==='g'?1:2)+' '+weightUnit():''}</p><div class="range" style="margin-top:16px">${[[30,'30天'],[90,'90天'],[0,'全部']].map(([n,l])=>act('range',l,range===n?'active':'',`data-value="${n}"`)).join('')}</div>${chart(ws)}</section><section class="card"><h2>体重明细</h2>${all.slice(0,20).map(r=>recordCard(r)).join('')||empty('留下一次测量','每一条记录都可以编辑和回顾。')}</section></div><div class="stack">${(['狗','猫'].includes(pet()?.type)?['疫苗','驱虫','护理']:['护理','疫苗','驱虫']).map(k=>`<section class="card"><div class="section-title"><h2>${k==='疫苗'?'疫苗档案':k==='驱虫'?'驱虫档案':'日常护理'}</h2>${act('record','添加','textbtn',`data-kind="${k}"`)}</div>${records().filter(r=>r.kind===k).map(r=>recordCard(r)).join('')||empty('还没有'+k+'记录','按真实情况填写，支持补记历史。')}</section>`).join('')}</div></div>`}
function growth(){let body='';if(growthView==='健康档案')body=health();else if(growthView==='相册'){const pics=records().flatMap(r=>(r.photos||[]).map(src=>({src,r})));body=pics.length?`<div class="photo-grid">${pics.map(p=>act('viewrecord',image(p.src,'','成长照片'),'',`data-id="${p.r.id}"`)).join('')}</div>`:empty('把喜欢的瞬间留下','在日常或里程碑记录中添加照片，就会出现在这里。',act('record','添加照片日常','btn','data-kind="日常"'))}else {const rs=records().filter(r=>recordFilter==='全部'||r.kind===recordFilter);let month='';body=`<div class="chips">${['全部',...Object.keys(types)].map(k=>act('recordfilter',k,'chip '+(recordFilter===k?'active':''),`data-value="${k}"`)).join('')}</div><div class="timeline-list">${rs.map(r=>{let h='';if(month!==r.day.slice(0,7)){month=r.day.slice(0,7);h=`<div class="month-label">${month.slice(0,4)} <span class="tiny">年</span> ${Number(month.slice(5))} <span class="tiny">月</span></div>`}return h+recordCard(r)}).join('')||empty('这里还没有记录','试着记下一个普通但可爱的瞬间。',act('record','写下第一篇','btn','data-kind="日常"'))}</div>`}return title('A STORY THAT GROWS',`${esc(pet()?.name||'它')}的成长册`,'健康与回忆，都好好留在这里。',act('record',icon('plus')+' 记录','btn','data-kind="日常"'))+demoNotice()+`<div class="tabs">${['全部记录','健康档案','相册'].map(v=>act('growthtab',v,growthView===v?'active':'',`data-value="${v}"`)).join('')}</div>`+(pet()?body:needPet())}
function select(name,vals,value){return `<select aria-label="${({city:"城市",district:"区域",type:"宠物类型",size:"体型",personality:"性格",intent:"交友意向",time:"空闲时间"})[name]}" data-filter="${name}">${vals.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`}
function reasons(f){const p=pet(),rs=[];if(f.district===near.district&&near.district!=='全部区域')rs.push('同区域');else if(f.city===near.city)rs.push('同城');if(p?.type===f.type&&p?.size===f.size)rs.push('同为'+f.size+f.type);if(p?.breed&&p.breed===f.breed)rs.push('同品种');if(p?.intent===f.intent)rs.push(f.intent+'意向相同');if(p?.time===f.time)rs.push('空闲时间相近');return rs.join(' · ')}
function nearPage(){const fs=friends.filter(f=>!db().blocked.includes(f.id)&&f.city===near.city&&(near.district==='全部区域'||f.district===near.district)&&(near.type==='全部宠物'||f.type===near.type)&&(near.size==='全部体型'||f.size===near.size)&&(near.personality==='全部性格'||f.personality===near.personality)&&(near.intent==='全部意向'||f.intent===near.intent)&&(near.time==='全部时间'||f.time===near.time));return title('GOOD COMPANY, CLOSE BY','附近，也有小伙伴。','找合拍的宠友，从共同的生活开始。')+`<div class="demo-notice"><span>示例宠友目录 · 手动选择地区，无需定位权限</span></div><div class="filter-panel">${select('city',Object.keys(regions),near.city)}${select('district',regions[near.city],near.district)}${select('type',['全部宠物',...PET_TYPES],near.type)}${select('size',['全部体型','小型','中型','大型'],near.size)}${select('personality',['全部性格','活泼','慢热','亲人'],near.personality)}${select('intent',['全部意向','遛宠搭子','经验交流','同品种交流'],near.intent)}${select('time',['全部时间','周末','工作日傍晚'],near.time)}</div><div class="section-title"><p class="tiny muted">${near.city} · 找到 ${fs.length} 位示例宠友</p>${act('resetfilters','重置筛选','textbtn')}</div><div class="pet-grid">${fs.map(f=>act('friend',`${image(P[f.photo],'',f.name)}<div class="friend-info"><div class="section-title"><h3>${f.name}</h3><span class="tiny muted">${f.district}</span></div><p class="tiny muted">${f.breed} · ${f.age} · ${f.owner}</p><div class="friend-tags"><span class="pill">${f.personality}</span><span class="pill">${f.intent}</span></div><p class="match">${reasons(f)||'查看资料，了解它的生活'}</p></div>`,'friend-card',`data-id="${f.id}"`)).join('')}</div>${!fs.length?empty('暂时没有合适的小伙伴','试试减少筛选条件，或切换所在地区。',act('resetfilters','放宽筛选条件','btn light')):''}<p class="footer-note">只展示大致区域，见面地点由双方协商。</p>`}
function samplePosts(){return [{id:'s1',owner:'阿橙',friend:'f1',petName:'年糕',city:'上海',district:'徐汇区',topic:'日常晒宠',day:daysAgo(0),title:'小狗的快乐，是草地给的',memo:'傍晚一起散步的这一个小时，是今天最喜欢的时间。你们最近都去哪里遛狗？',photos:[P.walk],avatar:'corgi',likes:24},{id:'s2',owner:'小林',friend:'f2',petName:'奶盖',city:'上海',district:'浦东新区',topic:'养宠经验',day:daysAgo(1),title:'把照护小事，变成共同的习惯',memo:'最近开始把每天的饮食和体重分开记，回看时清楚了很多。普通的日常，也值得认真收藏。',photos:[P.cat],avatar:'cat',likes:18},{id:'s3',owner:'一颗栗子',friend:'f4',petName:'栗子',city:'杭州',district:'西湖区',topic:'求助交流',day:daysAgo(2),title:'慢热的小狗，怎样认识新朋友？',memo:'栗子第一次见其他小狗时有些害羞，想听听大家循序渐进交朋友的经验。',photos:[P.pomeranian],avatar:'pomeranian',likes:9}]}
function allPosts(){return [...db().posts,...samplePosts(),...speciesPosts()].filter(p=>!db().blocked.includes(p.friend||p.id)).sort((a,b)=>b.day.localeCompare(a.day)||(b.created||0)-(a.created||0))}
function postCard(p,detail=false){const mine=!!p.mine,liked=db().likes.includes(p.id),saved=db().bookmarks.includes(p.id),comments=db().comments[p.id]||[];return `<article class="card post"><div class="post-head">${image(mine?photo(db().pets.find(q=>q.id===p.pet)):P[p.avatar],'avatar-img',p.petName)}<div class="post-author"><b>${esc(p.owner)} · ${esc(p.petName)}</b><small>${esc(p.day)}${p.city?' · '+esc(p.city):''} · ${mine?'我的发布（本机）':'示例内容'}</small></div>${act('postmenu',icon('settings'),'textbtn',`data-id="${p.id}" aria-label="动态操作"`)}</div><span class="pill"># ${esc(p.topic)}</span>${p.title?`<h3>${esc(p.title)}</h3>`:''}<p class="post-text">${esc(p.memo||'')}</p>${p.photos?.length?`<div class="${p.photos.length>1?'post-multi':''}">${p.photos.map(src=>act('largephoto',image(src,p.photos.length>1?'':'post-image','社区照片'),'',`data-photo="${esc(src)}" style="padding:0;width:100%"`)).join('')}</div>`:''}<div class="post-tools">${act('like',icon('heart')+' '+((p.likes||0)+(liked?1:0)),liked?'on':'',`data-id="${p.id}" aria-label="点赞"`)}${act('comments',icon('community')+' '+comments.length,'',`data-id="${p.id}" aria-label="查看评论"`)}${act('bookmark',icon('star')+(saved?' 已收藏':' 收藏'),saved?'on':'',`data-id="${p.id}"`)}</div>${detail?`<div style="margin-top:16px"><h3>评论</h3>${comments.map(c=>`<div class="comment"><b>${esc(c.name)}</b><p>${esc(c.text)}</p><small class="muted">${esc(c.day)}</small> ${act('reply','回复','textbtn',`data-id="${p.id}" data-name="${esc(c.name)}"`)}</div>`).join('')||'<p class="tiny muted" style="margin-top:10px">还没有评论，留下第一句友好的交流吧。</p>'}</div><form id="commentform" data-id="${p.id}" style="margin-top:14px"><label class="field">写下你的评论<textarea name="text" maxlength="500" required placeholder="说说你的想法…"></textarea></label><p class="tiny muted">评论仅保存于本机演示空间。</p><div class="form-actions"><button class="btn" type="submit">保存评论</button></div></form>`:''}</article>`}
function community(){const posts=allPosts().filter(p=>(feedSpecies==='全部宠物'||(p.mine?db().pets.find(q=>q.id===p.pet)?.type:friends.find(f=>f.id===p.friend)?.type)===feedSpecies)&&(topic==='全部'||p.topic===topic)&&(feedView==='推荐'||feedView==='同城'&&p.city===(pet()?.city||db().profile.city)||feedView==='关注'&&db().following.includes(p.friend||p.id)));return title('LIFE IS BETTER, SHARED','分享日常，交换温暖。','晒晒小可爱，也聊聊养宠的大小事。',act('publish',icon('plus')+' 发布','btn'))+`<div class="demo-notice"><span>社区原型 · 发布、评论、关注仅在本机保存</span></div><div class="filter-panel"><select aria-label="社区宠物类型" data-community-species>${['全部宠物',...PET_TYPES].map(t=>`<option ${t===feedSpecies?'selected':''}>${t}</option>`).join('')}</select></div><div class="tabs">${['推荐','同城','关注'].map(v=>act('feedtab',v,feedView===v?'active':'',`data-value="${v}"`)).join('')}</div><div class="chips">${['全部','日常晒宠','成长瞬间','养宠经验','求助交流'].map(v=>act('topic',v,'chip '+(topic===v?'active':''),`data-value="${v}"`)).join('')}</div><div class="feed">${posts.map(p=>postCard(p)).join('')||empty('这里还安安静静的',feedView==='关注'?'从宠友详情关注感兴趣的伙伴，或先去看看推荐内容。':'换一个主题看看，或分享你的第一篇日常。',act('recommended','浏览推荐','btn light'))}</div>`}
function profile(){return title('YOUR LITTLE FAMILY','我的养宠生活','把关心留给它，把琐事交给记录。')+demoNotice()+`<div class="profile-grid"><div class="stack"><section class="card"><div class="profile-top">${image(photo(pet()),'avatar-img','当前宠物')}<div style="flex:1"><h2>${esc(db().profile.name)}</h2><p class="tiny muted">${esc(db().profile.city||'尚未设置地区')} · ${db().pets.length} 位家庭成员</p></div>${act('editprofile','编辑','textbtn')}</div>${db().profile.bio?`<p class="subtitle">${esc(db().profile.bio)}</p>`:''}</section><section class="card"><div class="section-title"><h2>我的宠物</h2>${act('newpet','添加 '+icon('plus'),'textbtn')}</div>${db().pets.map(p=>`<div class="pet-list-item">${image(photo(p),'avatar-img',p.name)}<div><b>${esc(p.name)}</b><p class="tiny muted">${esc(p.breed||p.type)} ${p.id===pet()?.id?'<span class="selected">· 当前查看</span>':''}</p></div>${act('selectpet','切换','textbtn',`data-id="${p.id}"`)}${act('editpet','编辑','textbtn',`data-id="${p.id}"`)}</div>`).join('')||needPet()}</section></div><div class="stack"><section class="card menu-list">${[['myposts','camera','我的发布与草稿'],['bookmarks','star','我的收藏'],['invitations','community','结伴邀请草稿'],['reminders','bell','护理计划'],['feedback','community','意见与建议'],['feedbackhistory','book','我的反馈回执'],['privacy','shield','隐私设置'],['export','download','导出成长记录'],['reset','settings',isDemo()?'重置示例体验':'清除个人数据']].map(([a,i,l])=>act(a,icon(i)+`<span>${l}</span>`+icon('arrow'),'menu-row')).join('')}</section><p class="privacy-note">${icon('shield')} 当前为浏览器本地版本。照片与记录不会自动同步到其他设备；更换域名或清理浏览器前，请先导出备份。</p></div></div>`}
function render(){nav();$('#main').innerHTML=({home,growth,near:nearPage,community,profile})[tab]()+`<p class="footer-note">爪爪日记 PAWDIARY · 每一种陪伴都值得记录<br>${act('feedback','告诉我们你的想法','textbtn')}</p>`;document.querySelector('.app').classList.remove('loaded');requestAnimationFrame(()=>document.querySelector('.app').classList.add('loaded'))}
const scrolls={};function go(t){scrolls[tab]=window.scrollY||0;tab=t;render();window.scrollTo({top:scrolls[t]||0,behavior:'instant'})}
let modalOriginal='', closingDraft=null;
function openModal(h,body){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${h}</h2>${act('close',icon('close'),'close','aria-label="关闭"')}</div><div class="modal-body">${body}</div>`;modalDirty=false;modalDraftType=null;modalOriginal='';if(!d.open)d.showModal();d.scrollTop=0;}
function closeModal(force=false){if(modalDirty&&!force){if(modalDraftType==='post'||modalDraftType==='record'){const form=$('#modal form');closingDraft={type:modalDraftType,data:draftData(),id:form?.dataset.id||''};openModal('先把这份记录留住？',`<p>内容尚未保存，可以存为草稿，下次接着写。</p><div class="stack">${act('saveclosing','保存草稿并退出','btn')}${act('continueclosing','继续编辑','btn outline')}${act('discardclosing','放弃本次编辑','btn danger')}</div>`)}else if(confirm('当前内容尚未保存，确定放弃并退出吗？')){$('#modal').close();modalDirty=false}return}$('#modal').close();modalDirty=false;modalDraftType=null;returnAfter=null}
function switchMode(mode){state.mode=mode;state.seen=true;persist();closeModal(true);render();if(mode==='personal'&&!pet())petForm();else toast(mode==='demo'?'已进入示例体验，个人记录保持独立':'已回到个人空间')}
function welcome(){const d=$('#modal');d.innerHTML=`<div class="welcome"><span class="brandmark">${icon('dog')}</span><div class="eyebrow">WELCOME TO PAWDIARY</div><h2>陪它，慢慢长大。</h2><p>记住每一次成长，照顾每一个日常，<br>遇见附近同样爱它们的人。</p>${image(P.walk,'','草地上的小狗')}${act('demo','先体验示例','btn')}${act('personal','添加我的宠物','btn outline')}<p style="font-size:11px;margin-top:17px">无需注册即可体验 · 记录保存在当前浏览器</p></div>`;d.showModal()}
function field(label,name,value='',type='text',required=false,extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function selectField(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${o}</option>`).join('')}</select></label>`}
function formButtons(label='保存'){return `<p class="form-error" id="formerror" role="alert"></p><div class="form-actions">${act('close','取消','btn outline')}<button class="btn" type="submit">${label}</button></div>`}
function photoField(){return `<label class="field">添加照片 <small>（选填，最多 3 张）</small><input type="file" name="photos" accept="image/*" multiple></label><div class="upload-preview" id="uploadpreview">${pendingPhotos.map(src=>image(src)).join('')}</div>${pendingPhotos.length?act('clearphotos','移除照片','textbtn'):''}`}
function recordForm(kind='日常',id='',from=null,draft=null){if(!pet()){toast('先为宠物建立档案，再开始记录');petForm();return}const r=draft?(draft.kind==='体重'?{...draft,value:Number(draft.value)/(draft.unit==='g'?1000:1)}:draft):(id?db().records.find(x=>x.id===id):{});if(!r)return;kind=r.kind||kind;pendingPhotos=[...(r.photos||[])];const name=r.title||'',day=r.day||today();let fields='';if(kind==='体重')fields=field('体重数值','value',r.value?Number((Number(r.value)*((r.unit||weightUnit())==='g'?1000:1)).toFixed(3)):'','number',true,'min="0.001" max="1000000" step="0.001" inputmode="decimal"')+selectField('体重单位','unit',['kg','g'],r.unit||weightUnit());else if(kind==='疫苗')fields=field('疫苗名称','title',name,'text',true,'maxlength="80" placeholder="填写实际接种名称"')+field('接种医院（选填）','hospital',r.hospital||'');else if(kind==='驱虫')fields=selectField('驱虫类型','subtype',['体内','体外','内外同驱'],r.subtype||from?.subtype||'体外')+field('产品名称（选填）','product',r.product||'');else fields=field(kind==='里程碑'?'里程碑名称':kind==='护理'?'护理内容':'标题（选填）','title',name,'text',kind==='里程碑',`maxlength="80" placeholder="${kind==='护理'?speciesCare(pet()?.type):'给这段回忆起个名字'}"`);if(kind==='里程碑')fields=`<div class="chips">${['第一次到家','生日快乐','第一次出游'].map(v=>act('milestone',v,'chip',`data-value="${v}"`)).join('')}</div>`+fields;openModal(id?'编辑'+kind:'记录'+kind,`<form id="recordform" data-kind="${kind}" data-id="${id}"><p class="tiny muted" style="margin-bottom:18px">${esc(pet().name)} · 默认仅自己可见${isDemo()?' · 示例空间':''}</p><input type="hidden" name="pet" value="${pet().id}">${fields}${field(kind==='疫苗'?'接种日期':'记录日期','day',day,'date',true,`max="${today()}"`)}${['疫苗','驱虫'].includes(kind)?field('下一次计划日期（选填）','next',r.next||'','date',false)+`<p class="tiny muted" style="margin:-8px 0 16px">按实际安排填写；本页提供站内提醒，不自动决定护理周期。</p>`:''}<label class="field">${kind==='日常'?'写下今天的小事':'补充说明'}<textarea name="memo" maxlength="2000" placeholder="记录值得记住的细节…">${esc(r.memo||'')}</textarea></label>${photoField()}${formButtons(id?'保存修改':'保存记录')}</form>`);modalDraftType='record';modalOriginal=kind}
function petForm(id='',newType=''){const p=id?db().pets.find(x=>x.id===id):{type:newType};pendingPhotos=p.photo&&photo(p)?[photo(p)]:[];openModal(id?'编辑宠物档案':'认识你的家庭成员',`<form id="petform" data-id="${id}">${field('宠物名字','name',p.name||'','text',true,'maxlength="20" placeholder="它叫什么名字？"')}<div class="form-row">${selectField('宠物类型','type',['请选择宠物类型',...PET_TYPES],p.type||'请选择宠物类型')}${field('品种（选填）','breed',p.breed||'','text',false,'maxlength="40"')}</div><div class="form-row">${field('生日（选填）','birthday',p.birthday||'','date',false,`max="${today()}"`)}${field('到家日期（选填）','arrival',p.arrival||'','date',false,`max="${today()}"`)}</div><div class="form-row">${selectField('性别','sex',['未填写','公','母'],p.sex||'未填写')}${selectField('体型','size',['小型','中型','大型'],p.size||'小型')}</div>${selectField('所在城市','city',Object.keys(regions),p.city||db().profile.city||'上海')}${field('所在区域（选填）','district',p.district||'','text',false,'maxlength="30"')}<div class="form-row">${selectField('性格','personality',['慢热','亲人','活泼'],p.personality||'慢热')}${selectField('交友意向','intent',['经验交流','同品种交流',...(['狗'].includes(p.type)?['遛宠搭子']:[])],p.intent||'经验交流')}</div>${selectField('常见空闲时间','time',['周末','工作日傍晚'],p.time||'周末')}<label class="field">宠物头像（选填）<input name="photos" type="file" accept="image/*"></label><div class="upload-preview" id="uploadpreview">${pendingPhotos.map(src=>image(src)).join('')}</div>${formButtons(id?'保存档案':'建立档案')}</form>`)}
function petDetail(){const p=pet();if(!p){petForm();return}openModal(esc(p.name)+'的档案',`${photo(p)?image(photo(p),'details-photo',p.name):''}<h2>${esc(p.name)}</h2><p class="subtitle">${esc(p.breed||p.type)} · ${esc(p.sex||'性别未填写')}</p><div class="detail-facts"><div>${p.birthday?age(p.birthday):'未填写'}<small>年龄</small></div><div>${records().length}<small>成长记录</small></div><div>${p.arrival?Math.max(0,-dayDiff(p.arrival))+'天':'未填写'}<small>到家时长</small></div></div><p>所在地区：${esc([p.city,p.district].filter(Boolean).join(' · ')||'未填写')}</p><p>交友意向：${esc(p.intent||'未填写')}</p><div class="form-actions">${act('editpet','编辑档案','btn',`data-id="${p.id}"`)}</div>`)}
function friendDetail(id){const f=friends.find(x=>x.id===id);if(!f)return;const follow=db().following.includes(id);openModal('认识'+f.name,`${image(P[f.photo],'details-photo',f.name)}<div class="section-title"><h2>${f.name}</h2><span class="pill">示例宠友</span></div><p class="tiny muted">${f.breed} · ${f.age} · ${f.city}${f.district}</p><div class="friend-tags"><span class="pill">${f.personality}</span><span class="pill">${f.size}${f.type}</span><span class="pill">${f.intent}</span></div><p>${f.bio}</p><div class="detail-facts"><div>${f.owner}<small>主人昵称</small></div><div>${f.time}<small>常见空闲</small></div><div>${f.place}<small>交流场景</small></div></div><p class="tiny muted">匹配参考：${reasons(f)||'可以从共同的养宠兴趣聊起'}。公开页面只显示大致地区。</p><div class="form-actions">${act('follow',follow?'已关注':'关注（本机）','btn outline',`data-id="${f.id}"`)}${act('invite','体验结伴邀请','btn',`data-id="${f.id}"`)}</div><p class="tiny muted">此为示例资料，邀请仅保存为本机草稿，不会发送给真实用户。</p>`)}
function inviteForm(id){const f=friends.find(x=>x.id===id);openModal('与'+f.name+'结伴 · 演示',`<p>写下一个友好的邀请。当前仅生成本机草稿，不会对外发送。</p><form id="inviteform" data-id="${id}">${selectField('结伴意向','intent',f.type==='狗'?['一起遛狗','交流养宠经验']:['交流养宠经验','同品种交流'],f.type==='狗'?'一起遛狗':'交流养宠经验')}${field('建议日期','day',today(),'date',true,`min="${today()}"`)}${field('建议时间（选填）','time','','time')}${field('公共地点（选填）','place','','text',false,'maxlength="80" placeholder="例如：公园正门"')}<label class="field">留言<textarea name="memo" maxlength="300" required placeholder="介绍一下你和宠物，聊聊希望一起做什么…"></textarea></label>${formButtons('保存邀请草稿')}</form>`)}
function publishForm(sourceId='',id='',draft=null){const src=db().records.find(r=>r.id===sourceId),p=draft||(id?db().posts.find(p=>p.id===id):{});if(!pet()){toast('先添加宠物，就可以分享生活了');petForm();return}pendingPhotos=[...(p.photos||src?.photos||[])];openModal(id?'编辑动态':'分享一个小日常',`<p>发布内容在本机展示。发布前检查照片和文字，避免带入私人信息。</p><form id="postform" data-id="${id}" data-source="${sourceId||p.source||''}"><input type="hidden" name="pet" value="${p.pet||pet().id}">${field('标题（选填）','title',p.title||src?.title||'','text',false,'maxlength="80"')}<label class="field">正文<textarea name="memo" maxlength="2000" placeholder="今天有什么想分享的？">${esc(p.memo||src?.memo||'')}</textarea></label>${selectField('主题','topic',['日常晒宠','成长瞬间','养宠经验','求助交流'],p.topic||'日常晒宠')}${photoField()}<label class="check"><input name="location" type="checkbox" ${p.city?'checked':''}>附带所在城市（不公开详细位置）</label>${!sourceId&&!p.source?'<label class="check"><input name="sync" type="checkbox" checked>同时保存到成长记录</label>':'<p class="tiny muted">来自已有成长记录，发布不会重复新增成长事件；公开内容与原记录分别编辑。</p>'}${formButtons(id?'保存修改':'预览发布内容')}</form>`);modalDraftType='post'}
function postDetail(id){const p=allPosts().find(p=>p.id===id);if(p)openModal('动态与交流',postCard(p,true))}
function notifications(){openModal('近期护理计划',`<p>按记录中填写的下一次日期展示。提醒仅在站内查看。</p>${plans().length?planRows(plans()):empty('暂无护理计划','添加疫苗或驱虫记录时，可以填写下一次日期。',act('record','添加计划','btn','data-kind="驱虫"'))}`)}
function draftData(){const f=$('#modal form');if(!f)return null;return {...Object.fromEntries(new FormData(f)),photos:[...pendingPhotos],kind:f.dataset.kind,source:f.dataset.source}}
function saveDraft(){const d=draftData();if(!d)return;if(transact(()=>db().draft={type:modalDraftType,data:d})){closeModal(true);toast('草稿已保存，可在“我的发布与草稿”继续编辑')}}
async function loadPhotos(input){const files=[...input.files];if(!files.length)return;const isPet=input.closest('form')?.id==='petform',max=isPet?1:3;const submit=input.closest('form')?.querySelector('button[type=submit]');if(submit)submit.disabled=true;try{const imgs=[];for(const f of files.slice(0,max)){if(!f.type.startsWith('image/'))throw Error('请选择图片文件');if(f.size>20*1024*1024)throw Error('单张图片请控制在 20MB 以内');const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('照片读取失败，请重试'));reader.onload=()=>{const im=new Image();im.onerror=()=>reject(Error('暂不支持此图片格式，请选择 JPG 或 PNG'));im.onload=()=>{const scale=Math.min(1,1100/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.78))};im.src=reader.result};reader.readAsDataURL(f)});imgs.push(src)}pendingPhotos=isPet?imgs:[...pendingPhotos,...imgs].slice(0,3);$('#uploadpreview').innerHTML=pendingPhotos.map(src=>image(src)).join('');modalDirty=true;if(files.length>max)toast('本次最多选择 '+max+' 张照片')}catch(e){toast(e.message)}finally{if(submit)submit.disabled=false;input.value=''}}
function error(t){const node=$('#formerror');if(node)node.textContent=t;else toast(t)}
let pendingPost=null;
document.addEventListener('submit',async e=>{const f=e.target;if(!f.closest('#modal'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));
if(f.id==='feedbackform'){const message=d.message.trim();if(message.length<5){error('请至少填写5个字，帮助我们理解你的意见。');return}const button=f.querySelector('button[type=submit]');button.disabled=true;button.textContent='正在提交…';try{const key=f.dataset.requestId||uid();f.dataset.requestId=key;const response=await fetch('/api/feedback',{signal:AbortSignal.timeout(15000),method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({clientId:state.feedbackClientId||=(uid()),id:key,category:d.category,species:d.species,message,contact:d.contact.trim(),website:d.website||''})});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'暂时无法提交，请稍后重试。');state.feedbackReceipts||=[];if(!state.feedbackReceipts.some(r=>r.id===result.id))state.feedbackReceipts.unshift({id:result.id,category:d.category,time:new Date().toLocaleString('zh-CN')});persist();closeModal(true);openModal('谢谢，你的意见已收集',`<p>意见已保存到网站后台，我们会用它持续完善体验。</p><div class="invite-card"><b>提交成功</b><p>回执编号：${esc(result.id)}</p></div><div class="form-actions">${act('close','完成','btn')}</div>`)}catch(err){error(err.name==='TimeoutError'||err.name==='AbortError'?'网络响应超时，填写内容已保留，请重试。':err.message||'网络暂时不可用，填写内容已保留，请重试。')}finally{button.disabled=false;button.textContent='提交意见'}return;}if(f.id==='recordform'){const kind=f.dataset.kind,id=f.dataset.id;if(!d.day||dayDiff(d.day)>0){error('记录日期不能晚于今天；未来护理请填写在下一次计划中。');return}if(kind==='日常'&&!d.title.trim()&&!d.memo.trim()&&!pendingPhotos.length){error('写一点文字或添加一张照片吧。');return}if(kind==='体重'&&(!Number.isFinite(Number(d.value))||Number(d.value)<=0)){error('请输入大于 0 的体重数值。');return}if(d.next&&d.next<=d.day){error('下一次计划日期应晚于本次记录日期。');return}const r={...d,id:id||uid(),kind,value:kind==='体重'?Number(d.value)/(d.unit==='g'?1000:1):undefined,title:kind==='驱虫'?d.subtype+'驱虫':d.title||'',photos:[...pendingPhotos],created:Date.now()};if(transact(()=>{if(id)db().records=db().records.map(x=>x.id===id?r:x);else db().records.push(r);db().draft=null})){closeModal(true);render();toast(kind+'已保存，成长记录已更新');if(['日常','里程碑'].includes(kind))openModal('这个瞬间，已经留住了',`<p>已保存到${esc(pet().name)}的成长册，仅自己可见。也可以选择分享给社区。</p><div class="form-actions">${act('close','留在成长册','btn outline')}${act('sharerecord','预览并分享','btn',`data-id="${r.id}"`)}</div>`)}}
else if(f.id==='petform'){if(!d.name.trim()){error('给它起个名字吧。');return}if(!PET_TYPES.includes(d.type)){error('请选择宠物类型。');return}if(d.birthday&&d.arrival&&d.arrival<d.birthday){error('到家日期不能早于生日，请核对日期。');return}const id=f.dataset.id||uid(),old=db().pets.find(p=>p.id===id);if(transact(()=>{const p={...old,...d,name:d.name.trim(),photo:pendingPhotos[0]||old?.photo||'',id};if(old)db().pets=db().pets.map(x=>x.id===id?p:x);else db().pets.push(p);db().current=id})){closeModal(true);render();toast('宠物档案已保存')}}
else if(f.id==='postform'){if(!d.memo.trim()&&!d.title.trim()&&!pendingPhotos.length){error('添加文字或照片后再分享吧。');return}const p=db().pets.find(p=>p.id===d.pet)||pet();pendingPost={id:f.dataset.id||uid(),pet:p.id,petName:p.name,mine:true,owner:db().profile.name,title:d.title.trim(),memo:d.memo,topic:d.topic,day:today(),created:Date.now(),photos:[...pendingPhotos],city:d.location?p.city||db().profile.city:'',source:f.dataset.source||'',sync:!!d.sync,likes:0};openModal('发布前，确认一下',`<p>以下是将展示的内容。当前发布仅在本机演示，不会对外公开。</p>${postCard(pendingPost).replace(/<div class="post-tools">[\s\S]*?<\/div>/,'').replace(/<button[^>]*data-action="postmenu"[\s\S]*?<\/button>/,'')}<div class="form-actions">${act('backpublish','返回编辑','btn outline')}${act('confirmpost','确认发布（本机）','btn')}</div>`)}
else if(f.id==='commentform'){const t=d.text.trim();if(!t)return;if(transact(()=>{(db().comments[f.dataset.id]||=[]).push({id:uid(),name:db().profile.name,text:t,day:today()})})){postDetail(f.dataset.id);render();toast('评论已保存于本机')}}
else if(f.id==='inviteform'){if(dayDiff(d.day)<0){error('请选择今天或之后的日期。');return}if(transact(()=>db().invites.unshift({...d,id:uid(),friend:f.dataset.id,status:'未发送 · 本机草稿'}))){closeModal(true);toast('邀请草稿已保存，未对外发送')}}
else if(f.id==='profileform'){if(transact(()=>db().profile={...db().profile,...d})){closeModal(true);render();toast('个人资料已保存')}}
});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-community-species]')){feedSpecies=t.value;render()}if(t.matches('[data-filter]')){near[t.dataset.filter]=t.value;if(t.dataset.filter==='city')near.district='全部区域';render()}if(t.name==='photos')loadPhotos(t);if(t.name==='type'&&t.closest('#petform')){const q=t.closest('form').querySelector('[name=intent]');q.innerHTML=(t.value==='狗'?['遛宠搭子','经验交流','同品种交流']:['经验交流','同品种交流']).map(v=>`<option>${v}</option>`).join('')}if(t.name==='unit'&&t.closest('#recordform')){const q=t.closest('form').querySelector('[name=value]');if(q.value)q.value=Number((Number(q.value)*(t.value==='g'?1000:.001)).toFixed(6))}if(t.matches('[data-privacy]')){transact(()=>db().privacy[t.dataset.privacy]=t.checked);toast('设置已保存于本机')}});
document.addEventListener('input',e=>{if(e.target.closest('#modal form'))modalDirty=true});
function toggle(list,id){const a=db()[list],i=a.indexOf(id);if(i>=0)a.splice(i,1);else a.push(id)}
function personalPosts(saved=false){const ps=allPosts().filter(p=>saved?db().bookmarks.includes(p.id):p.mine);openModal(saved?'我的收藏':'我的发布与草稿',`${!saved&&db().draft?`<section class="invite-card"><b>未完成的${db().draft.type==='post'?'动态':'成长记录'}</b>${act('continuedraft','继续编辑','textbtn')}</section>`:''}${ps.map(p=>postCard(p)).join('')||empty(saved?'还没有收藏':'还没有发布','喜欢的内容和自己的分享，会在这里找到。')}`)}
function invitations(){openModal('结伴邀请草稿',`<p>这里保存本机邀请草稿，没有对外发送。接入真实多人服务后才能接收回复。</p>${db().invites.map(i=>`<div class="invite-card"><b>邀请 ${friends.find(f=>f.id===i.friend)?.name||'宠友'} · ${esc(i.intent)}</b><small>${esc(i.day)} ${esc(i.time)} · ${esc(i.place||'地点待商量')}</small><p>${esc(i.memo)}</p><span class="pill">${esc(i.status)}</span>${act('deleteinvite','删除草稿','textbtn',`data-id="${i.id}"`)}</div>`).join('')||empty('还没有邀请草稿','从附近宠友的资料页开始，写下一份友好的邀请。')}`)}
function removePost(id){transact(()=>{db().posts=db().posts.filter(p=>p.id!==id);delete db().comments[id]});closeModal(true);render();toast('动态已删除，原成长记录保留')}
document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){go(n.dataset.nav);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,value=b.dataset.value;
switch(a){case 'saveclosing':if(closingDraft&&transact(()=>db().draft=closingDraft)){closingDraft=null;closeModal(true);toast('草稿已保存')};break;case 'continueclosing':if(closingDraft){const d=closingDraft;closingDraft=null;if(d.type==='post')publishForm(d.data.source||'',d.id,d.data);else recordForm(d.data.kind,d.id,null,d.data);modalDirty=true};break;case 'discardclosing':closingDraft=null;closeModal(true);break;case 'close':closeModal();break;case 'demo':switchMode('demo');break;case 'personal':switchMode('personal');break;case 'record':recordForm(b.dataset.kind||'日常');break;case 'feedback':feedbackForm();break;case 'feedbackhistory':feedbackHistory();break;case 'newpet':petForm('',b.dataset.kind||'');break;case 'editpet':petForm(id);break;case 'petdetail':petDetail();break;case 'switchpet':openModal('我的家庭成员',db().pets.map(p=>`<div class="pet-list-item">${image(photo(p),'avatar-img',p.name)}<div><b>${esc(p.name)}</b><p class="tiny muted">${esc(p.breed||p.type)}</p></div>${act('selectpet',p.id===pet()?.id?'当前查看':'查看它','btn light small',`data-id="${p.id}"`)}</div>`).join('')+act('newpet','添加家庭成员','btn outline','style="margin-top:20px;width:100%"'));break;case 'selectpet':transact(()=>db().current=id);closeModal(true);render();toast('正在查看'+pet().name);break;case 'allrecords':growthView='全部记录';recordFilter='全部';go('growth');break;case 'growthtab':growthView=value;render();break;case 'recordfilter':recordFilter=value;render();break;case 'range':range=Number(value);render();break;case 'near':if(regions[pet()?.city]){near.city=pet().city;near.district='全部区域'}go('near');break;case 'resetfilters':near={city:near.city,district:'全部区域',type:'全部宠物',size:'全部体型',personality:'全部性格',intent:'全部意向',time:'全部时间'};render();break;case 'friend':friendDetail(id);break;case 'follow':transact(()=>toggle('following',id));friendDetail(id);render();break;case 'invite':inviteForm(id);break;case 'invitations':invitations();break;case 'deleteinvite':if(confirm('删除这份邀请草稿？')){transact(()=>db().invites=db().invites.filter(i=>i.id!==id));invitations()}break;case 'feedtab':feedView=value;render();break;case 'topic':topic=value;render();break;case 'recommended':feedView='推荐';feedSpecies='全部宠物';topic='全部';render();break;case 'publish':publishForm();break;case 'sharerecord':publishForm(id);break;case 'backpublish':publishForm(pendingPost.source,db().posts.some(p=>p.id===pendingPost.id)?pendingPost.id:'',pendingPost);break;case 'confirmpost':if(pendingPost&&transact(()=>{const p={...pendingPost};if(p.sync&&!p.source){p.source=uid();db().records.push({id:p.source,pet:p.pet,kind:'日常',day:p.day,title:p.title,memo:p.memo,photos:p.photos,created:p.created})}delete p.sync;const at=db().posts.findIndex(x=>x.id===p.id);if(at>=0)db().posts[at]=p;else db().posts.push(p);db().draft=null})){pendingPost=null;closeModal(true);feedView='推荐';feedSpecies='全部宠物';topic='全部';go('community');toast('动态已发布于本机演示空间')}break;case 'like':case 'bookmark':transact(()=>toggle(a==='like'?'likes':'bookmarks',id));if($('#modal').open&&$('#commentform'))postDetail(id);else if($('#modal').open&&['我的收藏','我的发布与草稿'].includes($('#modal h2')?.textContent))personalPosts($('#modal h2').textContent==='我的收藏');render();break;case 'comments':postDetail(id);break;case 'reply':{const input=$('#commentform textarea');input.value='回复 '+b.dataset.name+'：';input.focus();break}case 'postmenu':{const p=allPosts().find(p=>p.id===id);if(!p)break;openModal('动态操作',p.mine?`<div class="stack">${act('editpost','编辑动态','btn outline',`data-id="${id}"`)}${act('deletepost','删除动态','btn danger',`data-id="${id}"`)}</div>`:`<p>社区演示中的举报与屏蔽仅保存于本机。</p><div class="stack">${act('followpost',db().following.includes(p.friend)?'取消关注':'关注这位宠友','btn outline',`data-id="${id}"`)}${act('report','举报内容（本机）','btn outline',`data-id="${id}"`)}${act('block','屏蔽此作者','btn danger',`data-id="${id}"`)}</div>`);break}case 'followpost':{const p=allPosts().find(x=>x.id===id);transact(()=>toggle('following',p.friend||id));closeModal(true);render();toast('关注状态已更新');break}case 'editpost':publishForm('',id);break;case 'deletepost':if(confirm('删除这条动态？同步保存的成长记录会保留。'))removePost(id);break;case 'report':transact(()=>db().reports.push({post:id,day:today()}));closeModal(true);toast('举报已记录于本机演示，未提交审核服务');break;case 'block':{const p=allPosts().find(p=>p.id===id);transact(()=>db().blocked.push(p.friend||id));closeModal(true);render();toast('已在本机屏蔽此作者，可在隐私设置恢复');break}case 'reminders':notifications();break;case 'complete':{const r=db().records.find(r=>r.id===id);recordForm(r.kind,'',r,{kind:r.kind,title:r.kind==='疫苗'?r.title:'',subtype:r.subtype,product:r.product,photos:[]});break}case 'editrecord':recordForm('日常',id);break;case 'deleterecord':if(confirm('删除这条成长记录？已发布的动态将保留，可单独删除。')){transact(()=>db().records=db().records.filter(r=>r.id!==id));render();toast('记录已删除，相关摘要已更新')}break;case 'weightpoint':case 'viewrecord':{const r=db().records.find(r=>r.id===id);if(!r)break;openModal('成长记录',`${r.photos?.length?r.photos.map(src=>image(src,'details-photo','记录照片')).join(''):''}<span class="pill">${esc(r.kind)}</span><h2 style="margin:12px 0">${esc(r.kind==='体重'?r.value+' kg':r.title||r.kind)}</h2><p class="tiny muted">${esc(r.day)} · 仅自己可见</p><p style="white-space:pre-wrap;margin-top:12px">${esc(r.memo||'')}</p><div class="form-actions">${act('editrecord','编辑记录','btn',`data-id="${r.id}"`)}</div>`);break}case 'milestone':$('#recordform [name=title]').value=value;modalDirty=true;break;case 'largephoto':openModal('查看照片',image(b.dataset.photo,'full-img','放大照片'));break;case 'clearphotos':pendingPhotos=[];$('#uploadpreview').innerHTML='';modalDirty=true;break;case 'myposts':personalPosts();break;case 'bookmarks':personalPosts(true);break;case 'continuedraft':{const draft=db().draft;if(!draft)break;if(draft.type==='post')publishForm(draft.data.source||'',draft.id||'',draft.data);else recordForm(draft.data.kind||'日常',draft.id||'',null,draft.data);break}case 'editprofile':openModal('编辑个人资料',`<form id="profileform">${field('昵称','name',db().profile.name,'text',true,'maxlength="20"')}${selectField('城市','city',Object.keys(regions),db().profile.city)}${field('所在区域','district',db().profile.district,'text',false,'maxlength="30"')}<label class="field">自我介绍<textarea name="bio" maxlength="200">${esc(db().profile.bio)}</textarea></label>${formButtons()}</form>`);break;case 'privacy':openModal('隐私设置',`<p>健康记录默认私密，分享需要主动确认。当前个人内容仅保存在本机。</p><label class="switch-row"><span>愿意在附近展示资料<br><small class="muted">当前仅保存偏好，不会对外发布</small></span><input data-privacy="nearby" type="checkbox" ${db().privacy.nearby?'checked':''}></label><div class="switch-row"><span>位置公开范围</span><b>城市／区域</b></div><div class="switch-row"><span>健康记录默认范围</span><b>仅自己</b></div>${act('unblock','恢复所有已屏蔽作者','btn outline','style="margin-top:20px"')}`);break;case 'unblock':transact(()=>db().blocked=[]);closeModal(true);render();toast('已恢复显示');break;case 'export':{const blob=new Blob([JSON.stringify({app:'PawDiary',version:2,exported:today(),mode:state.mode,data:db()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='pawdiary-'+today()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前空间的记录备份');break}case 'reset':if(confirm(isDemo()?'重置示例宠物、互动和邀请？个人空间不受影响。':'清除当前浏览器中的个人档案与记录？此操作无法撤销，请先导出备份。')){transact(()=>{state[state.mode]=fresh(isDemo());if(isDemo())enrichDemo(state.demo)});closeModal(true);render();toast('当前空间已重置')}break;
}});
$('#modal').addEventListener('cancel',e=>{if(modalDirty){e.preventDefault();closeModal()}else returnAfter=null});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('beforeunload',e=>{if(modalDirty){e.preventDefault();e.returnValue=''}});
render();if(!state.seen)welcome();

